    {"/esoui/art/buttons/gamepad/xbox/nav_xbone_right_shoulder_hold_ru.dds", "/esoui/art/buttons/gamepad/ps5/nav_ps5_right_shoulder_hold_ru.dds"},
}

local ps5ButtonMapApplied = false

function kpuiPS5ButtonMap:Initialize()
    for _, redirect in ipairs(xboxToPs5Redirects) do
        RedirectTexture(redirect[1], redirect[2])
    end
end

function kpuiPS5ButtonMap:Reverse()
    for _, redirect in ipairs(xboxToPs5Redirects) do
        RedirectTexture(redirect[2], redirect[1])
    end
end

function kpuiPS5ButtonMap:SetEnabled(enabled)
    if enabled == ps5ButtonMapApplied then
        return
    end

    if enabled then
        self:Initialize()
    else
        self:Reverse()
    end

    ps5ButtonMapApplied = enabled
end

local KELA_PS5_BUTTON_MAP_CHANGED = "KELA_PS5_BUTTON_MAP_CHANGED"

function KelaSetupPS5ButtonMap()
    if KelaPadUI.KelaPS5ButtonMapInitialized then
        return
    end
    KelaPadUI.KelaPS5ButtonMapInitialized = true

    CALLBACK_MANAGER:RegisterCallback(KELA_PS5_BUTTON_MAP_CHANGED, function()
        kpuiPS5ButtonMap:SetEnabled(KelaGetSetting_Bool(SETTING_TYPE_KELA, KELA_SETTING_PANEL_FEATURES_PS5_BUTTONS))
    end)

    kpuiPS5ButtonMap:SetEnabled(KelaGetSetting_Bool(SETTING_TYPE_KELA, KELA_SETTING_PANEL_FEATURES_PS5_BUTTONS))
end
